private Map<TopicPartition, Long> beginningOrEndOffset(Collection<TopicPartition> partitions,
                                                       long timestamp,
                                                       Timer timer,
                                                       boolean updatePartitionEndOffsetsFlag) {
    metadata.addTransientTopics(topicsForPartitions(partitions));
    try {
        Map<TopicPartition, Long> timestampsToSearch = partitions.stream()
                .distinct()
                .collect(Collectors.toMap(Function.identity(), tp -> timestamp));

        ListOffsetResult result = fetchOffsetsByTimes(timestampsToSearch, timer, false, updatePartitionEndOffsetsFlag);

        return result.fetchedOffsets.entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey, entry -> entry.getValue().offset));

private RequestFuture<ListOffsetResult> sendListOffsetRequest(final Node node,
                                                              final Map<TopicPartition, ListOffsetsPartition> timestampsToSearch,
                                                              boolean requireTimestamp) {
    ListOffsetsRequest.Builder builder = ListOffsetsRequest.Builder
            .forConsumer(requireTimestamp, isolationLevel)
            .setTargetTimes(ListOffsetsRequest.toListOffsetsTopics(timestampsToSearch))
            .setTimeoutMs(requestTimeoutMs);

    log.debug("Sending ListOffsetRequest {} to broker {}", builder, node);
    return client.send(node, builder)

public static class Builder extends AbstractRequest.Builder<ListOffsetsRequest> {
    private final ListOffsetsRequestData data;

    public static Builder forConsumer(boolean requireTimestamp,
                                      IsolationLevel isolationLevel) {
        return forConsumer(requireTimestamp, isolationLevel, false, false, false, false);
    }

    public static Builder forConsumer(boolean requireTimestamp,
                                      IsolationLevel isolationLevel,
                                      boolean requireMaxTimestamp,
                                      boolean requireEarliestLocalTimestamp,
                                      boolean requireTieredStorageTimestamp,
                                      boolean requireEarliestPendingUploadTimestamp) {
        short minVersion = ApiKeys.LIST_OFFSETS.oldestVersion();
        if (requireEarliestPendingUploadTimestamp)
            minVersion = 11;
        else if (requireTieredStorageTimestamp)
            minVersion = 9;
        else if (requireEarliestLocalTimestamp)
            minVersion = 8;
        else if (requireMaxTimestamp)
            minVersion = 7;
        else if (isolationLevel == IsolationLevel.READ_COMMITTED)
            minVersion = 2;
        else if (requireTimestamp)
            minVersion = 1;
        return new Builder(minVersion, ApiKeys.LIST_OFFSETS.latestVersion(), CONSUMER_REPLICA_ID, isolationLevel);

private Builder(short oldestAllowedVersion,
                short latestAllowedVersion,
                int replicaId,
                IsolationLevel isolationLevel) {
    super(ApiKeys.LIST_OFFSETS, oldestAllowedVersion, latestAllowedVersion);
    data = new ListOffsetsRequestData()
              .setIsolationLevel(isolationLevel.id())
              .setReplicaId(replicaId);
}

